import time, statistics, numpy as np
# 벤치마크 원칙: 준비는 시간 밖에서, 워밍업, 여러 번 재고 분포를 본다
def benchmark(run, num_warmups=1, num_trials=5):
    for _ in range(num_warmups):
        run()                       # 첫 호출의 준비·캐시 비용을 버린다
    times = []
    for _ in range(num_trials):
        t0 = time.perf_counter()
        run()                       # GPU 라면 여기서 Event.record + synchronize
        times.append((time.perf_counter() - t0) * 1e3)
    return statistics.median(times), max(times)

def matmul_op(dim):
    a = np.random.rand(dim, dim).astype(np.float32)   # 입력 생성은 재지 않는다
    b = np.random.rand(dim, dim).astype(np.float32)
    return lambda: a @ b

for dim in [64, 128, 256, 512, 1024, 2048]:
    med, worst = benchmark(matmul_op(dim))
    gflops = 2 * dim**3 / (med / 1e3) / 1e9
    print(f"dim {dim:5d}: 중앙값 {med:8.3f} ms, 최악 {worst:8.3f} ms, {gflops:7.1f} GFLOP/s")

import numpy as np
# 연산 하나 = 커널 하나라고 보고, HBM 을 몇 번 훑는지 센다
class T:
    reads = writes = kernels = 0
    def __init__(s, a): s.a = a
    @staticmethod
    def op(f, *xs):
        T.kernels += 1; T.writes += 1
        T.reads += sum(isinstance(x, T) for x in xs)    # 텐서 입력만 HBM 읽기
        return T(f(*[x.a if isinstance(x, T) else x for x in xs]))
    def __mul__(s, o): return T.op(np.multiply, s, o)
    __rmul__ = __mul__
    def __add__(s, o): return T.op(np.add, s, o)
    __radd__ = __add__

def tanh(t): return T.op(np.tanh, t)
x = T(np.random.randn(1 << 20).astype(np.float32))
c = float(np.sqrt(2 / np.pi))           # 파이썬 실수 상수
y = 0.5 * x * (1 + tanh(c * (x + 0.044715 * x * x * x)))   # 나눠 쓴 GeLU
print("커널", T.kernels, "| 읽기", T.reads, "| 쓰기", T.writes,
      "| 합친 커널 대비", (T.reads + T.writes) / 2, "배")
ref = 0.5 * x.a * (1 + np.tanh(c * (x.a + 0.044715 * x.a**3)))
print("값 확인:", np.allclose(y.a, ref, atol=1e-6))
